        var base = (a % p + p) % p
        var exp = e
        var res = 1L
        while (exp > 0) {
            if (exp and 1L == 1L) res = (res * base) % p
            base = (base * base) % p
            exp = exp shr 1
        }
        return res
    }

    fact[0] = 1L
    for (i in 1..n) fact[i] = (fact[i - 1] * i) % p
    invFact[n] = modPow(fact[n], p - 2)
    for (i in n downTo 1) invFact[i - 1] = (invFact[i] * i) % p

    fun comb(nn: Int, kk: Int): Long {
        if (kk < 0 || kk > nn) return 0L
        return (((fact[nn] * invFact[kk]) % p) * invFact[nn - kk]) % p
    }

    val C = Array(n + 1) { IntArray(n + 1) }
    for (i in 0..n) {
        C[i][0] = 1
        for (j in 1..i) {
            C[i][j] = ((C[i - 1][j - 1] + C[i - 1][j]) % p).toInt()
        }
    }

    val dp = Array(n + 1) { LongArray(m + 1) }
    val ways = Array(n + 1) { LongArray(m + 1) }

    ways[0][0] = 1L

    for (len in 1..n) {
        for (k in 1..minOf(len, m)) {
            var sumWays = 0L
            var sumMad = 0L
            for (x in 0..k) {
                val y = k - x
                if (x > len || y > len) continue
                val leftLen = len - 1
                val rightLen = len - 1
                val waysLeft = if (x == 0) 1L else ways[leftLen][x]
                val waysRight = if (y == 0) 1L else ways[rightLen][y]
                val dpLeft = if (x == 0) 0L else dp[leftLen][x]
                val dpRight = if (y == 0) 0L else dp[rightLen][y]

                val waysHere = (waysLeft * waysRight) % p
                val combVal = comb(k - 1, x)
                val totalWays = (waysHere * combVal) % p

                val madContribution = (dpLeft + dpRight) % p

                sumWays = (sumWays + totalWays) % p
                sumMad = (sumMad + madContribution * totalWays) % p
            }
            ways[len][k] = sumWays
            dp[len][k] = sumMad % p
        }
    }

    var answer = 0L
    for (len in m..n) {
        answer = (answer + dp[len][m]) % p
    }

    println(answer % p)
