                if (left > len || right > len) continue
                val prevLen = len - 1
                val prevK = k - 1
                if (prevK < 0) {
                    if (k == 0) continue
                }
                val chooseLeft = C[len - 1][left]
                val chooseRight = C[len - 1 - left][right]
                val waysPrev = if (k == 0) if (len == 1) 1L else 0L else ways[prevLen][prevK]
                val dpPrev = if (k == 0) 0L else dp[prevLen][prevK]
                val curWays = (((chooseLeft * chooseRight) % p) * waysPrev) % p
