import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer

private const val MAXN = 500

fun modPow(a: Long, e: Long, mod: Long): Long {
    var base = a % mod
    var exp = e
    var res = 1L
    while (exp > 0) {
        if (exp and 1L == 1L) res = (res * base) % mod
        base = (base * base) % mod
        exp = exp shr 1
    }
    return res
}

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val st = StringTokenizer(br.readLine())
    val n = st.nextToken().toInt()
    val m = st.nextToken().toInt()
    val p = st.nextToken().toLong()

    // Precompute factorials and inverse factorials up to n
    val fact = LongArray(n + 1)
    val invFact = LongArray(n + 1)
    fact[0] = 1L
    for (i in 1..n) fact[i] = (fact[i - 1] * i) % p
    invFact[n] = modPow(fact[n], p - 2, p)
    for (i in n downTo 1) {
        invFact[i - 1] = (invFact[i] * i) % p
    }

    fun comb(nn: Int, kk: Int): Long {
        if (kk < 0 || kk > nn) return 0L
        return (((fact[nn] * invFact[kk]) % p) * invFact[nn - kk]) % p
    }

    // Precompute powers of 2 up to m
    val pow2 = LongArray(m + 1)
    pow2[0] = 1L
    for (i in 1..m) pow2[i] = (pow2[i - 1] * 2L) % p

    var answer = 0L

    // For each pair of computers (i, j), i < j
    for (i in 1..n) {
        for (j in i + 1..n) {
            val dist = (j - i).toLong()
            // Number of ways to choose which participants sit at i and j
            val waysChoose = (comb(m, 1) * comb(m - 1, 1)) % p // m * (m-1)
            // For each such choice, remaining m-2 participants can choose any a and b
            val remainingWays = (modPow(n.toLong(), (m - 2).toLong(), p) * pow2[m]) % p
            val contrib = (((dist % p) * waysChoose) % p * remainingWays) % p
            answer += contrib
            if (answer >= p) answer -= p
        }
    }

    println(answer % p)
}
